window.DABanks["t2-test-07"] = {
  title: { en: "Test 7 — The Split, the Leak, and the Order You Can Prove",
           ar: "اختبار 7 — التقسيم والتسريب والترتيب الذي تستطيع إثباته" },
  intro: { en: "Twenty-four questions on Lesson 7: the three parts and their three jobs, the three ways a result leaks and what each one is worth on the rental file, the fold-to-fold spread that decides which comparisons are real, and the four gates a new feature must pass. Every hint, explanation and answer stays hidden until you ask for it; opening an answer marks that question as not counted. Allow about forty minutes.",
           ar: "أربعةٌ وعشرون سؤالًا على الدرس 7: الأقسامُ الثلاثة ووظائفها الثلاث، والطرقُ الثلاث التي تتسرّب بها النتيجة وما تساويه كلٌّ منها في ملف الإيجارات، وتشتُّتُ الطيّات الذي يحدّد أيَّ المقارنات حقيقي، والبواباتُ الأربع التي يجب أن تمرّ بها السمةُ الجديدة. ويبقى كلُّ تلميح وشرح وجواب مخفيًّا حتى تطلبه؛ وفتحُ الجواب يجعل ذلك السؤال غيرَ محسوب. واحسب نحو أربعين دقيقة." },
  questions: [

  { id: "t2l7q01", type: "tf", level: "easy", topics: ["t2-optimised-score", "t2-spent-holdout"],
    q: { en: "A held-out set that you never fitted a parameter on, but did use six times to choose between cleaning recipes, still gives an unbiased estimate of future error.",
         ar: "المجموعةُ المحجوزة التي لم تضبط عليها وسيطًا قط، لكنك استعملتها ستَّ مرات للاختيار بين وصفات التنظيف، تعطي مع ذلك تقديرًا غير متحيّز للخطأ المستقبلي." },
    truth: false,
    hint: { en: "Ask what else, besides a median or a scaler, counts as something you fitted.",
            ar: "اسأل: ما الذي يُعدّ شيئًا ضبطتَه، غيرَ الوسيط أو المقياس؟" },
    explain: { en: "The choice of recipe is itself a parameter, and you selected it to minimise the error on those rows. The reported number is then the smallest of six draws, which is biased downwards by however much the six recipes disagree — in this chapter's own Concept 1 table the four candidates spanned nearly six shekels. No <code>fit</code> call has to touch the rows for them to stop being independent.",
              ar: "اختيارُ الوصفة وسيطٌ بنفسه، وقد انتقيتَه ليصغّر الخطأ على تلك الصفوف. فالرقمُ المبلَّغ عنه هو أصغرُ ست سحبات، وهو متحيّز إلى الأدنى بمقدار ما تختلف به الوصفاتُ الست — وفي جدول المفهوم 1 في هذا الفصل امتدّ المرشَّحون الأربعة نحوَ ستة شواكل. ولا يلزم أن يلمس نداءُ <code>fit</code> الصفوفَ لتكفّ عن كونها مستقلّة." } },

  { id: "t2l7q02", type: "mcq", level: "easy", topics: ["t2-three-parts", "t2-choose-on-validation"],
    q: { en: "What is the validation set for?",
         ar: "ما وظيفةُ مجموعة التحقّق؟" },
    options: [
      { en: "To compare candidate recipes and choose one, as many times as you need, without spending the set you will report from.",
        ar: "لمقارنة الوصفات المرشَّحة واختيار واحدة، بعددِ ما تحتاج من المرات، بلا إنفاق المجموعة التي ستُبلّغ منها." },
      { en: "To fit the parameters that the training rows are too few to estimate reliably.",
        ar: "لضبط الوسائط التي تقلّ صفوفُ التدريب عن تقديرها تقديرًا موثوقًا." },
      { en: "To give a second, independent estimate of the final error, so you can average the two and reduce the noise.",
        ar: "لإعطاء تقدير ثانٍ مستقلّ للخطأ النهائي، فتتوسّط الاثنين وتقلّل الضجيج." },
      { en: "To check that the training and test sets came from the same distribution before you trust either.",
        ar: "للتحقّق من أن مجموعتَي التدريب والاختبار جاءتا من التوزيع نفسه قبل أن تثق بأيٍّ منهما." } ],
    answer: 0,
    hint: { en: "Think about which of the three parts is allowed to be read many times.",
            ar: "فكّر: أيُّ الأقسام الثلاثة يُسمح بقراءته مرات كثيرة؟" },
    explain: { en: "Validation exists so that choosing can happen somewhere other than the set you report from — it is <em>supposed</em> to become biased, and that is why a third part is needed. The answer about fitting parameters is the tempting one, because it sounds like a use for extra rows; but every parameter is fitted on train, and fitting on validation would make it part of the training set. Averaging two estimates does not help when one of them is the set you selected on, and a distribution check is a real activity that has nothing to do with why this part exists.",
              ar: "وُجدت مجموعةُ التحقّق ليحدث الاختيارُ في مكان غير المجموعة التي تُبلّغ منها — فهي <em>يُفترض</em> أن تصير متحيّزة، ولهذا يلزم قسمٌ ثالث. والجوابُ عن ضبط الوسائط هو المغري، فيبدو استعمالًا لصفوف زائدة؛ لكنّ كلَّ وسيط يُضبَط على التدريب، والضبطُ على التحقّق سيجعله جزءًا من مجموعة التدريب. وتوسيطُ تقديرين لا يفيد حين يكون أحدهما المجموعةَ التي انتقيتَ عليها، وفحصُ التوزيع نشاطٌ حقيقي لا علاقةَ له بسبب وجود هذا القسم." } },

  { id: "t2l7q03", type: "mcq", level: "easy", topics: ["t2-what-fits"],
    q: { en: "Which one of these steps may safely run <em>before</em> the train/validation/test split?",
         ar: "أيُّ هذه الخطوات يجوز أن تعمل بأمان <em>قبل</em> تقسيم التدريب والتحقّق والاختبار؟" },
    options: [
      { en: "Multiplying the five areas recorded in dunum by a thousand.",
        ar: "ضربُ المساحات الخمس المسجَّلة بالدونم بألف." },
      { en: "Filling the blank areas with the column's median.",
        ar: "تعويضُ المساحات الفارغة بوسيط العمود." },
      { en: "Clipping the rents to the 1.5 × IQR fence.",
        ar: "قصُّ الإيجارات إلى سياج 1.5 × IQR." },
      { en: "Replacing each agency with the median rent of its listings.",
        ar: "استبدالُ كل وكالة بوسيط إيجار إعلاناتها." } ],
    answer: 0,
    hint: { en: "For each step, ask whether it reads a number out of the data or brings one with it.",
            ar: "اسأل عن كل خطوة: هل تقرأ رقمًا من البيانات أم تأتي به معها؟" },
    explain: { en: "A dunum is a thousand square metres whether or not you have the file, so the repair is knowledge you brought and it may run anywhere. The other three all read a number out of the rows: a median, a pair of quartiles, a per-group mean. The fence is the trap worth naming — its <em>multiplier</em> is fixed at 1.5, which makes it look like a constant, but <code>Q1</code> and <code>Q3</code> are fitted, so the fence as a whole is a fitted parameter.",
              ar: "الدونمُ ألفُ متر مربع، ملكتَ الملفَّ أو لم تملكه، فالإصلاحُ معرفةٌ جئتَ بها ويجوز أن يعمل في أي موضع. والثلاثةُ الأخرى تقرأ كلُّها رقمًا من الصفوف: وسيطًا أو زوجَ أرباع أو متوسطَ مجموعة. والسياجُ هو الفخُّ الجديرُ بالتسمية — فـ<em>مضاعِفُه</em> مثبَّت عند 1.5، وهذا يجعله يبدو ثابتًا، لكنّ <code>Q1</code> و<code>Q3</code> مضبوطان، فالسياجُ كلُّه وسيطٌ مضبوط." } },

  { id: "t2l7q04", type: "multi", level: "medium", topics: ["t2-what-fits", "t2-fit-before-split"],
    q: { en: "Select every step that must run <strong>after</strong> the split, because it fits a parameter from the data.",
         ar: "اختر كلَّ خطوة يجب أن تعمل <strong>بعد</strong> التقسيم، لأنها تضبط وسيطًا من البيانات." },
    options: [
      { en: "The one-hot category list for <code>agency</code>.",
        ar: "قائمةُ فئات الترميز الأحادي لـ<code>agency</code>." },
      { en: "The quartile edges used to band <code>area_m2</code>.",
        ar: "حدودُ الأرباع المستعملة لتنطيق <code>area_m2</code>." },
      { en: "The <code>CITY_MAP</code> dictionary that turns 26 spellings into 5 city names.",
        ar: "قاموسُ <code>CITY_MAP</code> الذي يحوّل 26 هجاءً إلى 5 أسماء مدن." },
      { en: "Selecting the twenty columns most correlated with the rent.",
        ar: "انتقاءُ العشرين عمودًا الأشدَّ ارتباطًا بالإيجار." },
      { en: "Parsing <code>listed_on</code> with the two declared date formats.",
        ar: "تحليلُ <code>listed_on</code> بصيغتَي التاريخ المعلنتين." } ],
    answer: [0, 1, 3],
    hint: { en: "A literal you wrote down is not fitted; a value the code computed from the rows is.",
            ar: "الثابتُ الذي كتبتَه ليس مضبوطًا؛ والقيمةُ التي حسبها الكودُ من الصفوف مضبوطة." },
    explain: { en: "The category list, the band edges and the correlation-based selection are all computed from rows, so all three must come after the split; the selection is the worst of them because it consults the target with twenty degrees of freedom. <code>CITY_MAP</code> and <code>FORMATS</code> are declared literals — somebody wrote the eleven keys and the two format strings by hand — so they carry no information from any particular file and may run on either side. The distinction is not how gentle the step is, but whether a number came out of the data.",
              ar: "قائمةُ الفئات وحدودُ النطاقات والانتقاءُ بالارتباط تُحسَب كلُّها من الصفوف، فيجب أن تأتي ثلاثتُها بعد التقسيم؛ والانتقاءُ أسوأُها فهو يستشير الهدفَ بعشرين درجةَ حرية. و<code>CITY_MAP</code> و<code>FORMATS</code> ثوابتُ معلَنة — فقد كتب أحدٌ المفاتيحَ الأحد عشر ونصَّي الصيغة باليد — فلا تحمل معلومةً من ملفّ بعينه ويجوز أن تعمل في أي الجانبين. والفرقُ ليس في لطف الخطوة بل في هل خرج رقمٌ من البيانات." } },

  { id: "t2l7q05", type: "fill", level: "easy", topics: ["t2-fitted-edges", "t2-binning"],
    q: { en: "Complete the two-step rule for band edges: use the first function once, on the training rows, to learn the edges; use the second one from then on, with those stored edges, on every other frame.",
         ar: "أكمل القاعدةَ ذات الخطوتين لحدود النطاقات: استعمل الدالةَ الأولى مرة واحدة على صفوف التدريب لتعلّم الحدود؛ واستعمل الثانيةَ من حينها، بتلك الحدود المحفوظة، على كل إطار آخر." },
    code: "edges = pd.____1____(train[\"area_m2\"], q=4, retbins=True)[1]\nbands = pd.____2____(other[\"area_m2\"], bins=edges, include_lowest=True)",
    blanks: [ { accept: ["qcut"], label: { en: "learn", ar: "تعلّم" } },
              { accept: ["cut"],  label: { en: "apply", ar: "طبّق" } } ],
    hint: { en: "One of the two reads quartiles out of whatever column you hand it. That is the one you may only use once.",
            ar: "إحداهما تقرأ الأرباعَ من أي عمود تسلّمه لها. وتلك هي التي لا يجوز استعمالها إلا مرة." },
    explain: { en: "<code>qcut</code> computes quartiles from the column it is given, so running it on validation or on next month's file re-fits the edges to that file — the leak in its least obvious costume, and the same silent failure as re-running <code>get_dummies</code> per file. <code>cut</code> takes the boundaries as an argument and computes nothing, which is exactly what applying a stored parameter should look like.",
              ar: "تحسب <code>qcut</code> الأرباعَ من العمود المُعطى لها، فتشغيلُها على التحقّق أو على ملف الشهر القادم يعيد ضبطَ الحدود على ذلك الملف — وهو التسريبُ في أقلّ أزيائه بديهيةً، والفشلُ الصامت نفسه الذي في إعادة تشغيل <code>get_dummies</code> لكل ملف. و<code>cut</code> تأخذ الحدودَ وسيطًا ولا تحسب شيئًا، وهذا بالضبط ما ينبغي أن يبدو عليه تطبيقُ وسيط محفوظ." } },

  { id: "t2l7q06", type: "order", level: "medium", topics: ["t2-dedupe-then-split", "t2-choose-on-validation", "t2-overlap-measured"],
    q: { en: "Put the stages of an honest analysis in the order they must happen.",
         ar: "رتّب مراحل تحليل أمين بالترتيب الذي يجب أن تحدث به." },
    items: [
      { en: "De-duplicate on the business key, so one row means one flat.",
        ar: "أزِل التكرار على المفتاح العملي، فيعني الصفُّ شقةً واحدة." },
      { en: "Split into train, validation and test, recording the seed and proportions.",
        ar: "قسّم إلى تدريب وتحقّق واختبار، مسجّلًا البذرةَ والنسب." },
      { en: "Fit every parameter — fills, fences, category lists, band edges — on the training rows.",
        ar: "اضبط كلَّ وسيط — التعويضات والسياجات وقوائم الفئات وحدود النطاقات — على صفوف التدريب." },
      { en: "Compare candidate recipes on the validation rows and choose one.",
        ar: "قارن الوصفات المرشَّحة على صفوف التحقّق واختر واحدة." },
      { en: "Read the test rows, once, and report that number.",
        ar: "اقرأ صفوف الاختبار مرة واحدة وأبلِغ عن ذلك الرقم." } ],
    answer: [0, 1, 2, 3, 4],
    hint: { en: "Two of the five are irreversible once done in the wrong order: one contaminates the parts, the other spends the final number.",
            ar: "اثنتان من الخمس لا رجعةَ فيهما إن فُعلتا بالترتيب الخاطئ: إحداهما تلوّث الأقسام والأخرى تُنفق الرقمَ النهائي." },
    explain: { en: "De-duplication comes first because it decides what one row <em>is</em>, and doing it after the split leaves the same flat in two parts — worth 21.6667 against 62.2043 on this file. Fitting comes after the split or every parameter carries test information. Choosing comes after fitting and before the test read, and the test read is last and happens once. The order is not a style preference: three of the four boundaries between these stages are places where a specific, measurable leak enters.",
              ar: "تأتي إزالةُ التكرار أولًا لأنها تقرّر ما <em>هو</em> الصفُّ الواحد، وفعلُها بعد التقسيم يُبقي الشقةَ نفسها في قسمين — وذاك يساوي 21.6667 مقابل 62.2043 في هذا الملف. ويأتي الضبطُ بعد التقسيم وإلا حمل كلُّ وسيط معلومةَ اختبار. ويأتي الاختيارُ بعد الضبط وقبل قراءة الاختبار، وقراءةُ الاختبار أخيرةٌ وتحدث مرة واحدة. والترتيبُ ليس تفضيلَ أسلوب: فثلاثةٌ من الحدود الأربعة بين هذه المراحل مواضعُ يدخل فيها تسريبٌ محدَّد قابل للقياس." } },

  { id: "t2l7q07", type: "ordercode", level: "medium", topics: ["t2-fitted-edges", "t2-what-fits"],
    q: { en: "Order these statements so that the band feature is fitted on the training rows and applied to the validation rows without leaking.",
         ar: "رتّب هذه العبارات بحيث تُضبَط سمةُ النطاق على صفوف التدريب وتُطبَّق على صفوف التحقّق بلا تسريب." },
    items: [
      { code: "flats = rep.drop_duplicates(subset=[\"listing_id\"], keep=\"last\")" },
      { code: "shuffled = flats.sample(frac=1.0, random_state=3)" },
      { code: "tr, va = shuffled.iloc[:288], shuffled.iloc[288:384]" },
      { code: "edges = pd.qcut(tr[\"area_m2\"], q=4, retbins=True)[1]" },
      { code: "btr = pd.cut(tr[\"area_m2\"], bins=edges, include_lowest=True)" },
      { code: "bva = pd.cut(va[\"area_m2\"], bins=edges, include_lowest=True)" },
      { code: "table = tr[\"monthly_rent\"].groupby(btr).median()" } ],
    hint: { en: "Which line is the only one allowed to compute a boundary, and what must already exist before it runs?",
            ar: "أيُّ سطر هو الوحيد المسموح له بحساب حدّ، وما الذي يجب أن يكون موجودًا قبل أن يعمل؟" },
    explain: { en: "De-duplicate, shuffle, slice, then fit the edges on <code>tr</code> alone, then apply them with <code>cut</code> to both frames, then build the lookup table from the training bands. The two orderings that look fine and are not: computing <code>edges</code> before the slice (it then sees validation areas) and computing it from <code>shuffled</code> or <code>flats</code> (the same leak, more obviously). Note that both <code>cut</code> lines use the same <code>edges</code> object — that identity is the whole point, and it is what makes the validation bands comparable to the training ones.",
              ar: "أزِل التكرار واخلط واقطع، ثم اضبط الحدودَ على <code>tr</code> وحدها، ثم طبّقها بـ<code>cut</code> على الإطارين، ثم ابنِ جدولَ البحث من نطاقات التدريب. والترتيبان اللذان يبدوان سليمين وليسا كذلك: حسابُ <code>edges</code> قبل القطع (فترى حينئذ مساحاتِ التحقّق) وحسابُها من <code>shuffled</code> أو <code>flats</code> (التسريبُ نفسه بصورة أظهر). ولاحظ أن سطرَي <code>cut</code> يستعملان كائنَ <code>edges</code> نفسه — وتلك الهويةُ هي المغزى كلُّه، وهي ما يجعل نطاقاتِ التحقّق قابلةً للمقارنة بنطاقات التدريب." } },

  { id: "t2l7q08", type: "match", level: "easy", topics: ["t2-overlap-leak", "t2-fit-before-split", "t2-time-leak"],
    q: { en: "Match each leak to the cure that removes it.",
         ar: "طابِق كلَّ تسريبة بالعلاج الذي يزيلها." },
    leftHead: { en: "The leak", ar: "التسريب" },
    rightHead: { en: "The cure", ar: "العلاج" },
    pairs: [
      { l: { en: "The same flat appears in train and in test" , ar: "الشقةُ نفسها تظهر في التدريب والاختبار" },
        r: { en: "De-duplicate on the business key before splitting", ar: "أزِل التكرار على المفتاح العملي قبل التقسيم" } },
      { l: { en: "The scaler's minimum came from a test row", ar: "أدنى المقياس جاء من صفّ اختبار" },
        r: { en: "Fit every transformer inside the training rows only", ar: "اضبط كلَّ محوّل داخل صفوف التدريب وحدها" } },
      { l: { en: "A random split mixes June adverts into the training of February", ar: "تقسيمٌ عشوائي يخلط إعلانات حزيران في تدريب شباط" },
        r: { en: "Split by time: train on the past, test on the future", ar: "قسّم بالزمن: درّب على الماضي واختبر على المستقبل" } },
      { l: { en: "A recency column measured from the newest row in the whole file", ar: "عمودُ حداثة مقيسٌ من أحدث صفّ في الملف كله" },
        r: { en: "Declare the as-of date as a parameter of the split", ar: "أعلِن تاريخَ الأساس وسيطًا للتقسيم" } },
      { l: { en: "A feature built by dividing the deposit by the rent", ar: "سمةٌ مبنيّة بقسمة التأمين على الإيجار" },
        r: { en: "Drop it: the value will not exist at prediction time", ar: "أسقطها: فالقيمةُ لن توجد وقت التنبؤ" } } ],
    hint: { en: "One of the five cannot be fixed by any splitting or fitting discipline at all.",
            ar: "واحدةٌ من الخمس لا يُصلحها أيُّ انتظام في التقسيم أو الضبط على الإطلاق." },
    explain: { en: "The first three are the lesson's three leakage types and each has a structural cure. The fourth is the quieter version of time leakage: the as-of date is a parameter, and reading it from the data you happen to hold is the same mistake as reading a median from it. The fifth is different in kind — the ratio contains the target, so the column is disqualified rather than mis-fitted, which is why its cure is the only one that deletes the feature instead of changing when it is computed.",
              ar: "الثلاثُ الأولى هي أنواعُ التسريب الثلاثة في الدرس ولكلٍّ علاجٌ بنيوي. والرابعةُ هي النسخةُ الأهدأ من التسريب الزمني: فتاريخُ الأساس وسيطٌ، وقراءتُه من البيانات التي تصادف أن تملكها هي الخطأُ نفسه الذي في قراءة وسيط منها. والخامسةُ مختلفةٌ في النوع — فالنسبةُ تحتوي الهدف، فالعمودُ مستبعَدٌ لا مُسيءَ الضبط، ولهذا كان علاجُها الوحيدَ الذي يحذف السمةَ بدل تغيير وقت حسابها." } },

  { id: "t2l7q09", type: "contrast", level: "medium", topics: ["t2-three-parts", "t2-validation-cost"],
    q: { en: "Place each property under the part it describes.",
         ar: "ضع كلَّ خاصية تحت القسم الذي تصفه." },
    concepts: [ { en: "Validation set", ar: "مجموعة التحقّق" },
                { en: "Test set", ar: "مجموعة الاختبار" } ],
    rows: [
      { s: { en: "May be read many times without spoiling the analysis", ar: "يجوز قراءتها مرات كثيرة بلا إفساد التحليل" }, a: 0 },
      { s: { en: "Is read once, after every choice has been made", ar: "تُقرأ مرة واحدة بعد اتّخاذ كل الاختيارات" }, a: 1 },
      { s: { en: "Is expected to become biased as you work", ar: "يُتوقَّع أن تصير متحيّزة وأنت تعمل" }, a: 0 },
      { s: { en: "No parameter may ever be fitted on it", ar: "لا يجوز ضبطُ أي وسيط عليها قط" }, a: 2 },
      { s: { en: "Shares no business key with the training rows", ar: "لا تشارك صفوفَ التدريب أيَّ مفتاح عملي" }, a: 2 },
      { s: { en: "Holds 96 of this chapter's 480 flats", ar: "تضمّ 96 من شقق هذا الفصل الـ480" }, a: 2 },
      { s: { en: "Decides which recipe you keep", ar: "تحدّد أيَّ وصفة تُبقي" }, a: 0 } ],
    hint: { en: "Three of the seven are true of both, and one of those three is the property the whole lesson rests on.",
            ar: "ثلاثٌ من السبع صادقة على الاثنين، وإحدى تلك الثلاث هي الخاصيةُ التي يقوم عليها الدرسُ كله." },
    explain: { en: "Reading many times, becoming biased and choosing the recipe belong to validation alone; reading once belongs to test alone. Three are shared: no parameter is fitted on either, neither shares a key with train, and both hold 96 rows in this chapter's split. The row worth dwelling on is &ldquo;expected to become biased&rdquo; — validation is not damaged by being read repeatedly, that is its job, and the mistake is only ever to confuse its number with the test number.",
              ar: "القراءةُ مرات كثيرة والصيرورةُ متحيّزة واختيارُ الوصفة تخصّ التحقّقَ وحده؛ والقراءةُ مرة واحدة تخصّ الاختبارَ وحده. وثلاثٌ مشتركة: لا يُضبَط وسيطٌ على أيٍّ منهما، ولا تشارك أيٌّ منهما التدريبَ مفتاحًا، وتضمّ كلتاهما 96 صفًّا في تقسيم هذا الفصل. والصفُّ الجديرُ بالتأمّل «يُتوقَّع أن تصير متحيّزة» — فمجموعةُ التحقّق لا تتضرّر بقراءتها تكرارًا، فتلك وظيفتها، والخطأُ إنما هو خلطُ رقمها برقم الاختبار." } },

  { id: "t2l7q10", type: "compare", level: "medium", topics: ["t2-fit-before-split", "t2-small-leak-honest"],
    q: { en: "Both snippets encode <code>agency</code> by its median rent and score the result on the test rows. Which statement is true?",
         ar: "يرمّز المقطعان <code>agency</code> بوسيط إيجارها ويقيسان الناتج على صفوف الاختبار. فأيُّ العبارات صادقة؟" },
    codeA: "m = rep.groupby(\"agency\")[\"monthly_rent\"].median()\npred = te[\"agency\"].map(m).fillna(rep[\"monthly_rent\"].median())\nprint(mae(te[\"monthly_rent\"], pred))",
    codeB: "m = tr.groupby(\"agency\")[\"monthly_rent\"].median()\npred = te[\"agency\"].map(m).fillna(tr[\"monthly_rent\"].median())\nprint(mae(te[\"monthly_rent\"], pred))",
    options: [
      { en: "A reports 59.4892 and B reports 61.0215, and A is the one that cannot be defended, because its medians were computed from rows that include the test rents.",
        ar: "تُبلِّغ أ 59.4892 وتُبلِّغ ب 61.0215، وأ هي التي لا يمكن الدفاع عنها، فوسائطُها حُسبت من صفوف تشمل إيجارات الاختبار." },
      { en: "The two are equivalent, because a median is robust and a handful of extra rows cannot move it.",
        ar: "الاثنان مكافئان، فالوسيطُ حصين ولا تستطيع حفنةُ صفوف زائدة تحريكَه." },
      { en: "B is the leaky one, because fitting on the smaller frame makes its per-agency medians less reliable.",
        ar: "ب هي المتسرِّبة، فالضبطُ على الإطار الأصغر يجعل وسائطها لكل وكالة أقلَّ موثوقية." },
      { en: "A becomes acceptable once the fallback inside <code>fillna</code> is computed from <code>tr</code> instead.",
        ar: "تصير أ مقبولة متى حُسب المرتدُّ داخل <code>fillna</code> من <code>tr</code> بدلًا من ذلك." } ],
    answer: 0,
    hint: { en: "Look at which frame each <code>groupby</code> is called on, then ask what that frame contains.",
            ar: "انطر على أي إطار يُنادى كلُّ <code>groupby</code>، ثم اسأل: ماذا يحتوي ذلك الإطار؟" },
    explain: { en: "A fits on <code>rep</code>, the whole file, so its per-agency medians already contain the test rents; it reports 59.4892 against B's honest 61.0215, a difference of 1.5323 shekels. The &ldquo;equivalent&rdquo; option is the tempting one and it is half-true &mdash; the leak really is small here, because a median over roughly twenty-four rents barely moves &mdash; but small is not zero and the direction is always optimistic. Calling B leaky inverts the whole rule: fitting on fewer rows makes an estimate noisier, which is a cost you accept, not a leak. And repairing only the <code>fillna</code> fallback leaves the actual leak in the <code>groupby</code> untouched, which is the kind of partial fix that makes a review feel finished without making the number defensible.",
              ar: "تضبط أ على <code>rep</code>، وهو الملفُّ كله، فوسائطُها لكل وكالة تحتوي سلفًا إيجاراتِ الاختبار؛ وتُبلِّغ 59.4892 مقابل 61.0215 الأمينة لـب، فرقًا من 1.5323 شيكل. وخيارُ «المكافئ» هو المغري وهو نصفُ صحيح &mdash; فالتسريبُ صغيرٌ هنا حقًّا، إذ لا يكاد الوسيطُ على نحو أربعة وعشرين إيجارًا يتحرّك &mdash; لكنَّ الصغيرَ ليس صفرًا والاتجاهُ متفائلٌ دائمًا. وتسميةُ ب متسرِّبةً تقلب القاعدةَ كلها: فالضبطُ على صفوف أقلّ يجعل التقديرَ أكثر ضجيجًا، وتلك كلفةٌ تقبلها لا تسريبًا. وإصلاحُ مرتدِّ <code>fillna</code> وحده يترك التسريبَ الفعلي في <code>groupby</code> بلا مَساس، وهذا صنفُ الإصلاح الجزئي الذي يجعل المراجعةَ تبدو منتهية بلا أن يجعل الرقمَ قابلًا للدفاع." } },

  { id: "t2l7q11", type: "compare", level: "hard", topics: ["t2-fitted-edges", "t2-feature-gate"],
    q: { en: "Both snippets band the area into quartiles and look almost identical in a diff review. Which statement is true?",
         ar: "ينطّق المقطعان المساحةَ إلى أرباع ويبدوان شبهَ متطابقين في مراجعة فرق. فأيُّ العبارات صادقة؟" },
    codeA: "btr = pd.qcut(tr[\"area_m2\"], q=4)\nbva = pd.qcut(va[\"area_m2\"], q=4)\ntable = tr[\"monthly_rent\"].groupby(btr).median()\npred = bva.map(table)",
    codeB: "edges = pd.qcut(tr[\"area_m2\"], q=4, retbins=True)[1]\nbtr = pd.cut(tr[\"area_m2\"], bins=edges, include_lowest=True)\nbva = pd.cut(va[\"area_m2\"], bins=edges, include_lowest=True)\ntable = tr[\"monthly_rent\"].groupby(btr).median()\npred = bva.map(table)",
    options: [
      { en: "A cuts the validation rows at validation's own quartiles, so one flat can fall in different bands in the two frames, and <code>map</code> can silently return <code>NaN</code> because the interval labels need not match.",
        ar: "تقطع أ صفوفَ التحقّق عند أرباع التحقّق نفسه، فقد تقع شقةٌ واحدة في نطاقين مختلفين في الإطارين، وقد يُرجع <code>map</code> قيمًا <code>NaN</code> بصمت، فلافتاتُ المجالات لا يلزم أن تتطابق." },
      { en: "A is preferable when the two frames have different area distributions, because each frame gets bands suited to it.",
        ar: "أ أفضلُ حين يختلف توزيعُ المساحة في الإطارين، فينال كلُّ إطار نطاقاتٍ تناسبه." },
      { en: "B is the leaky version, because reusing the training edges imposes the training distribution on the validation rows.",
        ar: "ب هي النسخةُ المتسرِّبة، فإعادةُ استعمال حدود التدريب تفرض توزيعَ التدريب على صفوف التحقّق." },
      { en: "The two are equivalent, because <code>qcut</code> and <code>cut</code> produce the same intervals when both are given <code>q=4</code>.",
        ar: "الاثنان مكافئان، فـ<code>qcut</code> و<code>cut</code> تنتجان المجالاتَ نفسها متى أُعطيتا <code>q=4</code>." } ],
    answer: 0,
    hint: { en: "Ask what <code>qcut</code> reads out of the column it is handed, and then ask it twice.",
            ar: "اسأل: ماذا تقرأ <code>qcut</code> من العمود المسلّم إليها؟ ثم اسأل ذلك مرتين." },
    explain: { en: "A re-fits the quartiles on validation, which is both a leak and a correctness bug: the interval labels differ between the frames, so <code>map</code> matches against labels that may not exist and quietly yields <code>NaN</code>. The second option is the one to reject hardest, because it states the leak as if it were a feature &mdash; giving each frame &ldquo;bands suited to it&rdquo; means the same flat is described differently depending on which file it arrived in, which destroys the comparability the column exists for. Calling B leaky inverts the rule: imposing the fitted boundaries on later rows is precisely what applying a stored parameter means. And the two are not equivalent, because <code>cut</code> given explicit <code>bins</code> computes nothing at all. B is still imperfect for a different reason, which question 17 covers.",
              ar: "تعيد أ ضبطَ الأرباع على التحقّق، وهذا تسريبٌ وعطبُ صواب في آن: فلافتاتُ المجالات تختلف بين الإطارين، فيطابق <code>map</code> لافتاتٍ قد لا توجد ويعطي <code>NaN</code> بهدوء. والخيارُ الثاني هو الأحقُّ بالرفض، فهو يعرض التسريبَ كأنه ميزة &mdash; فإعطاءُ كل إطار «نطاقاتٍ تناسبه» يعني وصفَ الشقة نفسها وصفًا مختلفًا بحسب أي ملفٍّ وصلت فيه، وهذا يهدم القابليةَ للمقارنة التي وُجد العمودُ لها. وتسميةُ ب متسرِّبةً تقلب القاعدة: ففرضُ الحدود المضبوطة على صفوف لاحقة هو بالضبط معنى تطبيق وسيط محفوز. والاثنان غيرُ مكافئين، فـ<code>cut</code> مُعطاةً <code>bins</code> صريحة لا تحسب شيئًا على الإطلاق. وب ناقصةٌ مع ذلك لسبب آخر يغطّيه السؤال 17." } },

  { id: "t2l7q12", type: "error", level: "medium", topics: ["t2-fit-before-split", "t2-what-fits"],
    q: { en: "One line makes the reported error optimistic. Click it.",
         ar: "سطرٌ واحد يجعل الخطأ المبلَّغ عنه متفائلًا. انقره." },
    code: "flats = rep.drop_duplicates(subset=[\"listing_id\"], keep=\"last\")\nfill = flats[\"area_m2\"].median()\nflats = flats.assign(area_m2=flats[\"area_m2\"].fillna(fill))\nshuffled = flats.sample(frac=1.0, random_state=3)\ntr, va, te = shuffled.iloc[:288], shuffled.iloc[288:384], shuffled.iloc[384:]\ntable = tr.groupby(\"governorate\")[\"monthly_rent\"].median()\npred = te[\"governorate\"].map(table).fillna(tr[\"monthly_rent\"].median())\nprint(mae(te[\"monthly_rent\"], pred))",
    answer: 2,
    hint: { en: "Read the first four lines in order and ask when each number is computed relative to the split.",
            ar: "اقرأ الأسطر الأربعة الأولى بالترتيب واسأل: متى يُحسَب كلُّ رقم بالنسبة إلى التقسيم؟" },
    explain: { en: "Line 2 computes the median area over all 480 flats, and line 3 uses it to fill blanks in every part — so the imputed values in the test rows were built from the test rows. The de-duplication on line 1 is correct and correctly placed. Lines 6 and 7 are exemplary: the table is fitted on <code>tr</code> and the fallback too. The repair is to move lines 2 and 3 below line 5 and compute <code>fill</code> from <code>tr</code>, which is three characters of difference and the whole of the discipline.",
              ar: "يحسب السطر 2 وسيطَ المساحة على الشقق الـ480 كلها، ويستعمله السطر 3 لتعويض الفراغات في كل قسم — فالقيمُ المعوَّضة في صفوف الاختبار بُنيت من صفوف الاختبار. وإزالةُ التكرار في السطر 1 صحيحةٌ وفي موضعها الصحيح. والسطران 6 و7 نموذجيان: فالجدولُ مضبوط على <code>tr</code> والمرتدُّ كذلك. والإصلاحُ أن تنقل السطرين 2 و3 تحت السطر 5 وتحسب <code>fill</code> من <code>tr</code>، وذاك فرقُ ثلاثة أحرف وهو الانتظامُ كلُّه." },
    solution: { code: "flats = rep.drop_duplicates(subset=[\"listing_id\"], keep=\"last\")\nshuffled = flats.sample(frac=1.0, random_state=3)\ntr, va, te = shuffled.iloc[:288], shuffled.iloc[288:384], shuffled.iloc[384:]\n\nfill = tr[\"area_m2\"].median()                 # FIT: training rows only\ntr = tr.assign(area_m2=tr[\"area_m2\"].fillna(fill))\nva = va.assign(area_m2=va[\"area_m2\"].fillna(fill))\nte = te.assign(area_m2=te[\"area_m2\"].fillna(fill))\n\ntable = tr.groupby(\"governorate\")[\"monthly_rent\"].median()\npred = te[\"governorate\"].map(table).fillna(tr[\"monthly_rent\"].median())\nprint(mae(te[\"monthly_rent\"], pred))",
                en: "Split first, then fit the fill on the training rows and apply that one number to all three parts.",
                ar: "قسّم أولًا، ثم اضبط التعويضَ على صفوف التدريب وطبّق ذلك الرقمَ الواحد على الأقسام الثلاثة." } },

  { id: "t2l7q13", type: "error", level: "hard", topics: ["t2-date-features", "t2-feature-that-fails"],
    q: { en: "This builds date features for the Gaza rental file. One line is wrong in a way no count, histogram or <code>info()</code> would reveal. Click it.",
         ar: "هذا يبني سماتِ تاريخ لملف إيجارات غزة. وسطرٌ واحد خاطئ بصورة لا يكشفها عدٌّ ولا مدرَّج ولا <code>info()</code>. انقره." },
    code: "d = dtr[\"listed_dt\"]\nmonth = d.dt.month\nweekday = d.dt.day_name()\nis_weekend = d.dt.weekday >= 5\nrecency = (AS_OF - d).dt.days\nfeatures = pd.DataFrame({\"month\": month, \"weekday\": weekday,\n                         \"is_weekend\": is_weekend, \"recency\": recency})\nprint(features[\"is_weekend\"].mean().round(4))",
    answer: 4,
    hint: { en: "In pandas Monday is 0. Now count forward five days and ask which days that names — then ask which days the weekend falls on in Gaza.",
            ar: "في pandas الاثنينُ صفر. فعُدّ خمسةَ أيام إلى الأمام واسأل: أيَّ يومين يسمّي ذلك؟ ثم اسأل: على أيّ يومين تقع نهايةُ الأسبوع في غزة؟" },
    explain: { en: "<code>weekday &gt;= 5</code> selects Saturday and Sunday, because Monday is 0 — a European working week. In Gaza the weekend is Friday and Saturday, so the correct test is <code>d.dt.weekday.isin([4, 5])</code>. What makes this the most expensive kind of bug in the chapter is that it is statistically invisible: on these training rows both columns are true for 28.82&nbsp;% of rows, so the mean, the count and the dtype are all identical. Only <em>which</em> 83 rows differs, and no summary will tell you. The line arrives by copying a tutorial, which is also how it survives review.",
              ar: "تنتقي <code>weekday &gt;= 5</code> السبتَ والأحد، فالاثنينُ صفر — أسبوعُ عملٍ أوروبي. وفي غزة نهايةُ الأسبوع الجمعةُ والسبت، فالمحكُّ الصحيح <code>d.dt.weekday.isin([4, 5])</code>. والذي يجعل هذا أغلى صنف من العطب في الفصل أنه خفيٌّ إحصائيًّا: فعلى صفوف التدريب هذه يصدُق العمودان في 28.82&nbsp;% من الصفوف، فالمتوسطُ والعدُّ والنوعُ متطابقةٌ جميعًا. و<em>أيُّ</em> 83 صفًّا وحده يختلف، ولا تخبرك بذلك خلاصة. والسطرُ يصل بنقل درس، وبذلك ينجو من المراجعة أيضًا." },
    solution: { code: "is_weekend = d.dt.weekday.isin([4, 5])      # Friday = 4, Saturday = 5",
                en: "Name the days you mean instead of relying on where the week happens to start.",
                ar: "سَمِّ اليومين الذين تقصدهما بدل الاتّكال على حيث يصادف أن يبدأ الأسبوع." } },

  { id: "t2l7q14", type: "output", level: "easy", topics: ["t2-split-recorded", "t2-three-parts"],
    q: { en: "<code>split_listings</code> de-duplicates the 503 raw rows to 480 flats and cuts them 60/20/20. Type the three row counts and the three labelled counts it prints.",
         ar: "تزيل <code>split_listings</code> تكرارَ الصفوف الخام الـ503 إلى 480 شقة وتقطعها 60/20/20. اكتب أعدادَ الصفوف الثلاثة وأعدادَ المعلَّمة الثلاثة التي تطبعها." },
    code: "parts, split_log = split_listings(rep)\nprint(split_log[\"report\"].to_string(index=False))",
    blanks: [
      { accept: ["288"], label: { en: "train rows", ar: "صفوف التدريب" } },
      { accept: ["278"], label: { en: "train labelled", ar: "معلَّمة التدريب" } },
      { accept: ["96"],  label: { en: "valid rows", ar: "صفوف التحقّق" } },
      { accept: ["89"],  label: { en: "valid labelled", ar: "معلَّمة التحقّق" } },
      { accept: ["96"],  label: { en: "test rows", ar: "صفوف الاختبار" } },
      { accept: ["93"],  label: { en: "test labelled", ar: "معلَّمة الاختبار" } } ],
    hint: { en: "60 % and 20 % of 480 are exact. The labelled counts are smaller because nineteen rents are blank and the blanks do not divide evenly.",
            ar: "ستّون وعشرون في المئة من 480 أعدادٌ تامّة. وأعدادُ المعلَّمة أصغر لأن تسعةَ عشرَ إيجارًا فارغة والفراغاتُ لا تتوزّع بالتساوي." },
    explain: { en: "480 splits exactly into 288, 96 and 96. The labelled counts — 278, 89 and 93 — are what is left after the blank rents, and they matter because every MAE in the lesson is computed over labelled rows only, so the test number rests on 93 flats rather than 96. The lesson's habit of printing rows and labels side by side exists precisely so that nobody quotes an error without knowing how many rents it was averaged over.",
              ar: "تنقسم 480 بالتمام إلى 288 و96 و96. وأعدادُ المعلَّمة — 278 و89 و93 — هي ما يتبقّى بعد الإيجارات الفارغة، وهي مهمّة لأن كلَّ متوسط خطأ مطلق في الدرس محسوبٌ على الصفوف المعلَّمة وحدها، فرقمُ الاختبار يقوم على 93 شقة لا 96. وعادةُ الدرس في طبع الصفوف واللافتات جنبًا إلى جنب موجودةٌ بالضبط لئلّا يذكر أحدٌ خطأً بلا أن يعرف على كم إيجار تُوسِّط." } },

  { id: "t2l7q15", type: "output", level: "medium", topics: ["t2-bins-before-repair", "t2-interval-midpoint"],
    q: { en: "Four equal-width bands are cut from <code>area_m2</code> on the 288 training rows, first with the dunum areas left as they are and then after multiplying those five rows by a thousand. Type the four counts in each case.",
         ar: "تُقطَع أربعةُ نطاقات متساوية العرض من <code>area_m2</code> على صفوف التدريب الـ288، أولًا بترك مساحات الدونم كما هي ثم بعد ضرب تلك الصفوف الخمسة بألف. اكتب الأعدادَ الأربعة في كل حالة." },
    code: "before = pd.cut(dtr[\"area_m2\"], bins=4)\nprint([int(v) for v in before.value_counts().sort_index()])\n\ndtr = repair_area(dtr)\nafter = pd.cut(dtr[\"area_m2\"], bins=4)\nprint([int(v) for v in after.value_counts().sort_index()])",
    blanks: [
      { accept: ["[4, 55, 140, 73]", "[4,55,140,73]", "4, 55, 140, 73", "4,55,140,73"],
        label: { en: "before the repair", ar: "قبل الإصلاح" }, wide: true },
      { accept: ["[45, 91, 94, 42]", "[45,91,94,42]", "45, 91, 94, 42", "45,91,94,42"],
        label: { en: "after the repair", ar: "بعد الإصلاح" }, wide: true } ],
    hint: { en: "Equal-width bins divide the range, and the range starts at the smallest value. Ask what the smallest area is in each case.",
            ar: "النطاقاتُ متساوية العرض تقسّم المدى، والمدى يبدأ من أصغر قيمة. فاسأل: ما أصغرُ مساحة في كل حالة؟" },
    explain: { en: "Before the repair the minimum is 0.1 m² — a flat recorded in dunum — so the range is 0.1 to 113.6 and the first band, 28 m² wide, catches only the five broken rows plus nothing else: 4, 55, 140, 73. A quarter of the band structure is spent on an error, and the third band has to absorb 140 rows. After multiplying the five by a thousand the minimum is 32.3, the range is sensible and the bands come out 45, 91, 94, 42, which is a shape you would choose on purpose. The counts are the fastest diagnostic for a unit error there is: a band holding single digits next to one holding half the file is almost always a broken scale rather than a real distribution.",
              ar: "قبل الإصلاح أصغرُ قيمة 0.1 م² — شقةٌ مسجَّلة بالدونم — فالمدى من 0.1 إلى 113.6 والنطاقُ الأول، وعرضُه 28 م²، يلتقط الصفوفَ الخمسة المعطوبة ولا شيء غيرها: 4 و55 و140 و73. فرُبعُ بناء النطاقات يُنفَق على خطأ، وعلى النطاق الثالث أن يستوعب 140 صفًّا. وبعد ضرب الخمسة بألف يصير الأصغرُ 32.3 والمدى معقولًا وتخرج النطاقاتُ 45 و91 و94 و42، وهو شكلٌ كنتَ ستختاره قصدًا. والأعدادُ أسرعُ تشخيص لخطأ وحدة على الإطلاق: فنطاقٌ يحمل أعدادًا أحادية بجانب نطاق يحمل نصفَ الملف هو في الغالب مقياسٌ معطوب لا توزيعٌ حقيقي." } },

  { id: "t2l7q16", type: "trace", level: "medium", topics: ["t2-fit-before-split", "t2-optimised-score"],
    q: { en: "Twelve listings are shuffled with a recorded seed and cut 50/25/25. State the value of <code>median</code> after line 10, and the value the last line prints.",
         ar: "تُخلَط اثنا عشر إعلانًا ببذرة مسجَّلة وتُقطَع 50/25/25. اذكر قيمةَ <code>median</code> بعد السطر 10، والقيمةَ التي يطبعها السطرُ الأخير." },
    code: "import pandas as pd\n\nrows = pd.read_csv(\"excerpt.csv\")        # 12 listings, rents 50 to 300\nshuffled = rows.sample(frac=1.0, random_state=3)\nn_train = int(len(shuffled) * 0.50)\nn_valid = int(len(shuffled) * 0.25)\ntrain = shuffled.iloc[:n_train]\nvalid = shuffled.iloc[n_train:n_train + n_valid]\ntest = shuffled.iloc[n_train + n_valid:]\nmedian = train[\"monthly_rent\"].median()\nprint(\"%.1f\" % median)\nprint(\"%.1f\" % rows[\"monthly_rent\"].median())",
    blanks: [
      { accept: ["147.5"], label: { en: "median (fitted on train)", ar: "‏median (مضبوط على التدريب)" } },
      { accept: ["217.5"], label: { en: "the last line", ar: "السطر الأخير" } } ],
    hint: { en: "The first is the median of six rents, the second of twelve. Only one of the two is a parameter you are allowed to use.",
            ar: "الأول وسيطُ ستة إيجارات والثاني وسيطُ اثني عشر. وواحدٌ منهما فقط وسيطٌ يحقّ لك استعماله." },
    explain: { en: "147.5 is the median of the six training rents; 217.5 is the median of all twelve. The gap of 70 shekels on twelve rows is a vivid version of the point Concept 4 measures at 1.53 shekels on 480: the second number is not a better estimate, it is one computed from rows the model is about to be scored on. Note also what the trace makes visible — the index after the shuffle is no longer 0 to 11, and those original labels are the only record of which flat went where.",
              ar: "147.5 وسيطُ إيجارات التدريب الستة؛ و217.5 وسيطُ الاثني عشر كلها. والفجوةُ من 70 شيكلًا على اثني عشر صفًّا صورةٌ حيّة للنقطة التي يقيسها المفهوم 4 بـ1.53 شيكل على 480: فالرقمُ الثاني ليس تقديرًا أحسن بل محسوبًا من صفوف يوشك النموذج أن يُقاس عليها. ولاحظ أيضًا ما يُظهره التتبُّع — فالفهرسُ بعد الخلط لم يبقَ من 0 إلى 11، وتلك اللافتاتُ الأصلية هي السجلُّ الوحيد لأيّ شقة ذهبت أين." } },

  { id: "t2l7q17", type: "mcq", level: "medium", topics: ["t2-fitted-edges"],
    q: { en: "Band edges were fitted on the training rows, whose largest area is 113.6 m². Next month's file contains a 140 m² flat. With <code>pd.cut(s, bins=edges, include_lowest=True)</code> and the stored edges unchanged, what happens to that row?",
         ar: "ضُبطت حدودُ النطاقات على صفوف التدريب وأكبرُ مساحة فيها 113.6 م². ويحتوي ملفُّ الشهر القادم شقةً من 140 م². فبـ<code>pd.cut(s, bins=edges, include_lowest=True)</code> والحدودِ المحفوظة بلا تغيير، ماذا يحدث لذلك الصف؟" },
    options: [
      { en: "Its band is <code>NaN</code>, with no error and no warning.",
        ar: "نطاقُه <code>NaN</code>، بلا خطأ ولا تحذير." },
      { en: "It is placed in the top band, because <code>pd.cut</code> clamps values beyond the last edge.",
        ar: "يوضَع في النطاق الأعلى، فـ<code>pd.cut</code> تحصر القيمَ بعد الحدّ الأخير." },
      { en: "<code>pd.cut</code> raises a <code>ValueError</code> naming the out-of-range value.",
        ar: "ترفع <code>pd.cut</code> خطأ <code>ValueError</code> يسمّي القيمةَ الخارجة عن المدى." },
      { en: "The edges are extended automatically to cover the new maximum.",
        ar: "تُمدَّد الحدودُ تلقائيًّا لتغطّي الأقصى الجديد." } ],
    answer: 0,
    hint: { en: "Think about which failures in this chapter were loud and which were quiet, and which kind pandas prefers.",
            ar: "فكّر: أيُّ أعطاب هذا الفصل كانت صاخبة وأيُّها هادئة، وأيَّ صنف يفضّل pandas؟" },
    explain: { en: "A silent <code>NaN</code> — the same failure shape as Lesson 5's unseen category and Lesson 3's unmatched city spelling, which is three lessons meeting one bug in three different objects. The clamping answer is the dangerous distractor because it is what you would <em>want</em> to happen, and believing it means you never write the line that makes it happen: the lesson's final version calls <code>.clip(edges[0], edges[-1])</code> before cutting. Raising would at least be loud, and automatic extension would be the leak, since the new file would be deciding its own boundaries.",
              ar: "<code>NaN</code> صامت — وهو شكلُ الفشل نفسه في الفئة غير المرئية في الدرس 5 والهجاءِ غير المطابَق للمدينة في الدرس 3، فثلاثةُ دروس تلقى عطبًا واحدًا في ثلاثة كائنات مختلفة. وجوابُ الحصر هو المضلّلُ الخطير فهو ما <em>تتمنّى</em> حدوثه، واعتقادُه يعني أنك لن تكتب السطرَ الذي يجعله يحدث: فالنسخةُ الأخيرة في الدرس تنادي <code>.clip(edges[0], edges[-1])</code> قبل القطع. ورفعُ الخطأ كان سيكون صاخبًا على الأقل، والتمديدُ التلقائي كان سيكون التسريب، إذ يقرّر الملفُّ الجديد حدودَه بنفسه." } },

  { id: "t2l7q18", type: "multi", level: "hard", topics: ["t2-feature-gate", "t2-overlap-leak"],
    q: { en: "You are predicting next month's rent for a flat. Select every candidate feature that is leaking, whatever split you use.",
         ar: "تتنبّأ بإيجار شقة للشهر القادم. اختر كلَّ سمة مرشَّحة تسرّب، أيًّا كان التقسيم الذي تستعمله." },
    options: [
      { en: "<code>deposit / monthly_rent</code>, the ratio that identified the two rent errors.",
        ar: "<code>deposit / monthly_rent</code>، النسبةُ التي عيّنت خطأَي الإيجار." },
      { en: "<code>times_posted</code>, the number of rows in the file sharing this <code>listing_id</code>.",
        ar: "<code>times_posted</code>، عددُ الصفوف في الملف التي تشارك هذا <code>listing_id</code>." },
      { en: "<code>recency</code>, days between the advert's date and a declared as-of date.",
        ar: "<code>recency</code>، الأيامُ بين تاريخ الإعلان وتاريخِ أساس معلَن." },
      { en: "<code>city_mean_rent</code>, the mean rent of the flat's city computed over the whole file.",
        ar: "<code>city_mean_rent</code>، متوسطُ إيجار مدينة الشقة محسوبًا على الملف كله." },
      { en: "<code>area_band</code>, with edges fitted on the training rows and stored.",
        ar: "<code>area_band</code>، بحدود مضبوطة على صفوف التدريب ومحفوظة." } ],
    answer: [0, 1, 3],
    hint: { en: "Two different failures are on this list: a column that contains the answer, and a column whose parameter was read from rows you may not touch.",
            ar: "في هذه القائمة فشلان مختلفان: عمودٌ يحتوي الإجابة، وعمودٌ قُرئ وسيطُه من صفوف لا يحقّ لك لمسها." },
    explain: { en: "Three leak, for two different reasons. The ratio and <code>times_posted</code> contain the answer: the first is built from the target by arithmetic, and the second counts the re-posts in a file that already includes the future, so no split rescues either. <code>city_mean_rent</code> is the Concept 4 leak — a legitimate feature with its parameter read from the whole file; move the mean inside the training rows and it becomes fine, which is what separates it from the first two. <code>recency</code> with a declared as-of date and a properly fitted <code>area_band</code> are both clean. The useful distinction: a disqualified column must be deleted, a mis-fitted one only has to be re-fitted.",
              ar: "ثلاثةٌ تسرّب لسببين مختلفين. فالنسبةُ و<code>times_posted</code> تحتويان الإجابة: فالأولى مبنيّة من الهدف حسابيًّا، والثانيةُ تعدّ إعادات النشر في ملفّ يشمل المستقبلَ سلفًا، فلا ينجي أيًّا منهما تقسيم. و<code>city_mean_rent</code> هو تسريبُ المفهوم 4 — سمةٌ مشروعة قُرئ وسيطُها من الملف كله؛ فانقل المتوسطَ داخل صفوف التدريب يصير سليمًا، وهذا ما يفصله عن الأولَيين. و<code>recency</code> بتاريخ أساس معلَن و<code>area_band</code> مضبوطًا ضبطًا سليمًا نظيفان كلاهما. والفرقُ المفيد: العمودُ المستبعَد يجب حذفُه، وسيّئُ الضبط لا يلزمه إلا إعادةُ ضبط." } },

  { id: "t2l7q19", type: "tf", level: "easy", topics: ["t2-time-measured"],
    q: { en: "On this rental file, splitting chronologically — fitting on February to April and testing on May and June — produced a worse error than the random split, which is the usual sign that time leakage was inflating the random result.",
         ar: "في ملف الإيجارات هذا، أنتج التقسيمُ الزمني — الضبطُ على شباط إلى نيسان والاختبارُ على أيار وحزيران — خطأً أسوأَ من التقسيم العشوائي، وهذه العلامةُ المعتادة على أن التسريبَ الزمني كان يضخّم النتيجةَ العشوائية." },
    truth: false,
    hint: { en: "Recall the two medians the lesson printed beside that comparison: the past's and the future's.",
            ar: "تذكّر الوسيطين الذين طبعهما الدرس بجانب تلك المقارنة: وسيطَ الماضي ووسيطَ المستقبل." },
    explain: { en: "The chronological split scored <strong>better</strong>: 55.4511 against the random split's 60.9140. The reason is in the medians — 200.0 in the past against 195.0 in the future — so the market barely moved over the window and predicting June from February to April is no harder. The honest conclusion is narrow and worth getting right: on this file, over this window, a random split cost approximately nothing. It does not license random splits on dated data generally, because you can only discover that by running the comparison, and the next batch could answer differently.",
              ar: "سجّل التقسيمُ الزمني <strong>أحسنَ</strong>: 55.4511 مقابل 60.9140 للتقسيم العشوائي. والسببُ في الوسيطين — 200.0 في الماضي مقابل 195.0 في المستقبل — فالسوقُ لم يتحرّك إلا قليلًا خلال النافذة، والتنبّؤُ بحزيران من شباط إلى نيسان ليس أصعب. والاستنتاجُ الأمين ضيّقٌ ويستحقّ الإصابة: في هذا الملف على هذه النافذة لم يكلّف التقسيمُ العشوائي شيئًا تقريبًا. وهذا لا يجيز التقسيماتِ العشوائية على البيانات المؤرَّخة عمومًا، فلا تكتشف ذلك إلا بإجراء المقارنة، والدفعةُ القادمة قد تجيب جوابًا آخر." } },

  { id: "t2l7q20", type: "mcq", level: "hard", topics: ["t2-fold-spread", "t2-decision-in-noise"],
    q: { en: "Five-fold cross-validation gives a median per governorate a mean MAE of 56.8610 with a standard deviation of 7.0358, and a median per raw city 58.5144 with 6.9438. What does this license you to say?",
         ar: "يعطي التحقّقُ المتقاطع بخمس طيّات وسيطَ المحافظة متوسطَ خطأ 56.8610 وانحرافًا 7.0358، ووسيطَ المدينة الخام 58.5144 و6.9438. فماذا يجيز لك هذا أن تقول؟" },
    options: [
      { en: "The two are indistinguishable on this data, so prefer the governorate grouping on a ground other than its score — it needs five parameters rather than twenty-six — and say that is why.",
        ar: "الاثنان لا يُفرَّق بينهما في هذه البيانات، ففضّل تجميعَ المحافظة على أساس غير نتيجته — فهو يحتاج خمسةَ وسائط لا ستةً وعشرين — وقل إن هذا هو السبب." },
      { en: "The governorate grouping is better, since 56.8610 is lower and both were measured on the same five folds.",
        ar: "تجميعُ المحافظة أحسن، فـ56.8610 أدنى وقد قِيس الاثنان على الطيّات الخمس نفسها." },
      { en: "Nothing: a standard deviation above ten per cent of the mean means the folds were built wrongly and the run must be repeated with more of them.",
        ar: "لا شيء: فانحرافٌ معياري يزيد على عشرة في المئة من المتوسط يعني أن الطيّات بُنيت خطأً ويجب إعادةُ التشغيل بعدد أكبر منها." },
      { en: "The raw-city grouping is better, because its standard deviation is lower and stability matters more than a 1.65-shekel mean difference.",
        ar: "تجميعُ المدينة الخام أحسن، فانحرافُه المعياري أدنى والثباتُ أهمّ من فرق متوسط بـ1.65 شيكل." } ],
    answer: 0,
    hint: { en: "Compare the gap between the means with the spread beside them, then ask what is left to decide on.",
            ar: "قارن الفجوةَ بين المتوسطين بالتشتُّت بجانبهما، ثم اسأل: ماذا بقي لتقرّر عليه؟" },
    explain: { en: "The gap is 1.6534 against a spread of about 7 — roughly a quarter of the noise — so the data cannot separate them, which is exactly why Lesson 7 retracts the way Concept 2 presented that comparison. Option two is the habit being broken: two means compared without the spread beside them. Option four makes the mirror-image error, since 6.94 against 7.04 is also well inside the noise. Option three invents a rule: a large fold spread on 384 rows is information about the sample size, and adding folds narrows the spread of the <em>mean</em> while leaving the underlying variability where it is. When two recipes tie, choose on something defensible without the data — simplicity, cost, or behaviour on unseen categories — and say so in those words.",
              ar: "الفجوةُ 1.6534 مقابل تشتُّت نحو 7 — نحوُ رُبع الضجيج — فالبياناتُ لا تفرّق بينهما، ولهذا بالضبط يسحب الدرس 7 الطريقةَ التي عرض بها المفهومُ 2 تلك المقارنة. والخيارُ الثاني هو العادةُ التي تُكسَر: متوسطان يُقارَنان بلا التشتُّت بجانبهما. والخيارُ الرابع يرتكب الخطأَ المعاكس، فـ6.94 مقابل 7.04 داخلَ الضجيج أيضًا بوضوح. والخيارُ الثالث يختلق قاعدة: فتشتُّتُ طيّات كبير على 384 صفًّا معلومةٌ عن حجم العيّنة، وزيادةُ الطيّات تضيّق تشتُّتَ <em>المتوسط</em> وتترك التغيُّرَ الكامن حيث هو. ومتى تعادلت وصفتان فاختر على شيء قابل للدفاع بلا البيانات — البساطة أو الكلفة أو السلوك على الفئات غير المرئية — وقل ذلك بتلك الكلمات." } },

  { id: "t2l7q21", type: "complete", level: "medium", topics: ["t2-cross-validation", "t2-cv-cost", "t2-sklearn-form"],
    q: { en: "This cross-validates a predictor over the rows you are allowed to fit and choose on. Complete the missing line so that the test rows stay unread.",
         ar: "هذا يتحقّق تقاطعيًّا من متنبِّئ على الصفوف التي يحقّ لك الضبطُ والاختيارُ عليها. أكمل السطرَ الناقص بحيث تبقى صفوفُ الاختبار غيرَ مقروءة." },
    code: "parts, _ = split_listings(rep)\n\npool = ____\nfolds = np.array_split(np.array(pool.sample(frac=1.0, random_state=7).index), 5)\n\nscores = []\nfor i in range(5):\n    hold, fit = pool.loc[folds[i]], pool.drop(folds[i])\n    fm = fit[\"monthly_rent\"].median()\n    pred = hold[\"governorate\"].map(fit.groupby(\"governorate\")[\"monthly_rent\"].median()).fillna(fm)\n    scores.append(mae(hold[\"monthly_rent\"], pred))",
    options: [
      { code: "pd.concat([parts[\"train\"], parts[\"valid\"]])" },
      { code: "pd.concat([parts[\"train\"], parts[\"valid\"], parts[\"test\"]])" },
      { code: "parts[\"train\"]" },
      { code: "rep" } ],
    answer: 0,
    hint: { en: "Cross-validation replaces the fixed validation set, so it may use those rows — but only those.",
            ar: "التحقّقُ المتقاطع يحلّ محلّ مجموعة التحقّق الثابتة، فيجوز له استعمالُ تلك الصفوف — لكن تلك وحدها." },
    explain: { en: "Cross-validation is a replacement for the fixed validation split, so the rows it may use are train plus validation — 384 of the 480 here — and the 96 test rows stay out so that they are still unread when the chapter finally reports a number. Pooling all three is the common and fatal version: it spends the test set on model selection and leaves nothing to report from. Using <code>train</code> alone works but throws away 96 rows for no reason, since the folds already provide the holding-out. Using <code>rep</code> is worse than all of them, because it is the raw 503-row frame and puts duplicated flats back into both halves of every fold.",
              ar: "التحقّقُ المتقاطع بديلٌ عن تقسيم التحقّق الثابت، فالصفوفُ التي يجوز له استعمالها هي التدريب مع التحقّق — 384 من الـ480 هنا — وتبقى صفوفُ الاختبار الـ96 خارجًا لتكون غيرَ مقروءة حين يُبلّغ الفصلُ أخيرًا عن رقم. وجمعُ الثلاثة هو النسخةُ الشائعة القاتلة: فهي تُنفق مجموعةَ الاختبار على انتقاء النموذج ولا تُبقي شيئًا للإبلاغ منه. واستعمالُ <code>train</code> وحدها ينفع لكنه يرمي 96 صفًّا بلا سبب، فالطيّاتُ توفّر الحجزَ سلفًا. واستعمالُ <code>rep</code> أسوأُ منها كلّها، فهو الإطارُ الخام ذو الـ503 صفوف ويعيد الشققَ المكرَّرة إلى نصفَي كل طيّة." },
    solution: { code: "pool = pd.concat([parts[\"train\"], parts[\"valid\"]])   # 384 rows; the 96 test rows stay unread",
                en: "Cross-validate over train and validation together, and keep the test set for the single final reading.",
                ar: "تحقّق تقاطعيًّا على التدريب والتحقّق معًا، وأبقِ مجموعةَ الاختبار للقراءة النهائية الواحدة." } },

  { id: "t2l7q22", type: "fill", level: "easy", topics: ["t2-as-of-date"],
    q: { en: "Repair the recency feature so that it is reproducible and leak-free. Replace the expression with the name of the declared constant the split specification carries.",
         ar: "أصلِح سمةَ الحداثة لتكون قابلةً للإعادة وبلا تسريب. استبدل بالتعبير اسمَ الثابت المعلَن الذي تحمله مواصفةُ التقسيم." },
    code: "# before: a different answer every week, and a parameter read from the data\n# recency = (pd.Timestamp.today() - d).dt.days\n# recency = (flats[\"listed_dt\"].max() - d).dt.days\nrecency = (____1____ - d).dt.days",
    blanks: [ { accept: ["AS_OF", "as_of"], label: { en: "the reference point", ar: "نقطة المرجع" } } ],
    hint: { en: "It is neither today nor anything the file can tell you. The lesson stores it beside the seed and the proportions.",
            ar: "ليست اليومَ ولا شيئًا يستطيع الملفُّ أن يخبرك به. والدرسُ يحفظها بجانب البذرة والنسب." },
    explain: { en: "<code>AS_OF</code> is a declared parameter that travels with the split, so all three parts and next month's file measure recency from the same instant. <code>today()</code> makes the column change weekly, which is not leakage but non-determinism — worse, because nobody can reproduce your report. <code>max()</code> is reproducible and still wrong: it reads its reference point out of rows that may include the test set. On this file the newest advert happens to sit in the training rows under every seed the lesson tried, so that bug would have passed every test — and 27 of the first 60 seeds would have exposed it. That is the argument for structure over luck.",
              ar: "<code>AS_OF</code> وسيطٌ معلَن يسافر مع التقسيم، فتقيس الأقسامُ الثلاثة وملفُّ الشهر القادم الحداثةَ من اللحظة نفسها. و<code>today()</code> يجعل العمودَ يتغيّر أسبوعيًّا، وهذا ليس تسريبًا بل لا حتمية — وهي أسوأ، فلا يستطيع أحدٌ إعادةَ إنتاج تقريرك. و<code>max()</code> قابلٌ للإعادة وخاطئٌ مع ذلك: فهو يقرأ نقطةَ مرجعه من صفوف قد تشمل مجموعةَ الاختبار. وفي هذا الملف يصادف أن يقع أحدثُ إعلان في صفوف التدريب تحت كل بذرة جرّبها الدرس، فكان ذلك العطبُ سينجح في كل اختبار — وكانت 27 من البذور الستين الأولى ستكشفه. وتلك هي الحجّةُ للبنية على الحظّ." } },

  { id: "t2l7q23", type: "write", level: "hard", topics: ["t2-dedupe-then-split", "t2-split-recorded", "t2-what-fits"],
    q: { en: "Write the honest version from scratch. Starting from <code>rep</code> (503 raw rows), de-duplicate on the business key, shuffle once with a recorded seed, cut 60/20/20, fit a median rent per governorate on the training rows only, and print the validation MAE. Do not fit anything on the whole frame.",
         ar: "اكتب النسخةَ الأمينة من الصفر. ابدأ من <code>rep</code> (503 صفوف خام)، وأزِل التكرار على المفتاح العملي، واخلط مرة واحدة ببذرة مسجَّلة، واقطع 60/20/20، واضبط وسيطَ إيجار لكل محافظة على صفوف التدريب وحدها، واطبع خطأ التحقّق. ولا تضبط شيئًا على الإطار كله." },
    starter: "flats = \nshuffled = \ntr, va = \ntable = \nprint(...)",
    lines: 10,
    checks: [
      { re: "drop_duplicates\\s*\\(", label: { en: "de-duplicates before splitting", ar: "يزيل التكرار قبل التقسيم" } },
      { re: "subset\\s*=", label: { en: "names the business key", ar: "يسمّي المفتاح العملي" } },
      { re: "random_state\\s*=", label: { en: "records the seed", ar: "يسجّل البذرة" } },
      { re: "iloc", label: { en: "cuts the shuffled frame into parts", ar: "يقطع الإطار المخلوط أقسامًا" } },
      { re: "tr\\s*\\.\\s*groupby", label: { en: "fits the table on the training rows", ar: "يضبط الجدول على صفوف التدريب" } },
      { re: "mae\\s*\\(", label: { en: "scores with the chapter's ruler", ar: "يقيس بمسطرة الفصل" } } ],
    forbid: [
      { re: "(flats|rep|shuffled)\\s*\\.\\s*groupby", label: { en: "fitting on a frame that contains validation or test rows", ar: "الضبط على إطار يحتوي صفوف التحقّق أو الاختبار" } },
      { re: "pd\\s*\\.\\s*qcut", label: { en: "re-fitting quartiles here", ar: "إعادة ضبط الأرباع هنا" } } ],
    hint: { en: "Four of the six required parts are about <em>where</em> a number comes from, not about what it is. Write the de-duplication above the shuffle.",
            ar: "أربعةٌ من الأجزاء الستة المطلوبة عن <em>من أين</em> يأتي الرقم لا عن ماهيته. واكتب إزالةَ التكرار فوق الخلط." },
    explain: { en: "The order is the answer: de-duplicate, shuffle, slice, then fit. Each boundary is a place a specific leak enters — de-duplicating after the slice leaves the same flat in two parts, and fitting before the slice puts validation rents into the table. Note that <code>drop_duplicates</code> needs <code>subset=[\"listing_id\"]</code>, because the nine reposts are not byte-identical and the bare call would miss them, and that <code>sort_values(\"listed_on\")</code> with <code>keep=\"last\"</code> is what makes the surviving copy the newest rather than an arbitrary one.",
              ar: "الترتيبُ هو الجواب: أزِل التكرار واخلط واقطع ثم اضبط. وكلُّ حدٍّ موضعٌ يدخل فيه تسريبٌ محدَّد — فإزالةُ التكرار بعد القطع تُبقي الشقةَ نفسها في قسمين، والضبطُ قبل القطع يضع إيجاراتِ التحقّق في الجدول. ولاحظ أن <code>drop_duplicates</code> تحتاج <code>subset=[\"listing_id\"]</code>، فالإعلاناتُ التسعة المعادة ليست متطابقة حرفيًّا والنداءُ المجرَّد سيُفلتها، وأن <code>sort_values(\"listed_on\")</code> مع <code>keep=\"last\"</code> هو ما يجعل النسخةَ الباقية أحدثَ لا اعتباطية." },
    solution: { code: "flats = (rep.sort_values(\"listed_on\")\n            .drop_duplicates(subset=[\"listing_id\"], keep=\"last\"))     # 503 -> 480\n\nshuffled = flats.sample(frac=1.0, random_state=3)\nn = len(shuffled)\ntr, va = shuffled.iloc[:int(n * 0.60)], shuffled.iloc[int(n * 0.60):int(n * 0.80)]\n\nm = tr[\"monthly_rent\"].median()                       # FIT: training rows only\ntable = tr.groupby(\"governorate\")[\"monthly_rent\"].median()\n\npred = va[\"governorate\"].map(table).fillna(m)\nprint(\"validation MAE %.4f\" % mae(va[\"monthly_rent\"], pred))",
                en: "De-duplicate on the key, shuffle with a recorded seed, slice, and let every fitted number come from <code>tr</code>.",
                ar: "أزِل التكرار على المفتاح، واخلط ببذرة مسجَّلة، واقطع، واجعل كلَّ رقم مضبوط يأتي من <code>tr</code>." } },

  { id: "t2l7q24", type: "mcq", level: "hard", topics: ["t2-feature-gate", "t2-feature-that-fails"],
    q: { en: "Lesson 4 used <code>deposit / monthly_rent</code> to find the two rent errors, and it worked beautifully. Lesson 7 refuses it as a feature. What is the difference?",
         ar: "استعمل الدرس 4 <code>deposit / monthly_rent</code> لاكتشاف خطأَي الإيجار، ونجح نجاحًا باهرًا. ويرفضه الدرس 7 سمةً. فما الفرق؟" },
    options: [
      { en: "In Lesson 4 it is a diagnostic computed by an analyst on rows that already have rents; as a feature it would be required on rows whose rent is the unknown, and it contains that unknown.",
        ar: "في الدرس 4 هو تشخيصٌ يحسبه محلّلٌ على صفوف لها إيجاراتٌ سلفًا؛ وسمةً سيكون مطلوبًا على صفوف إيجارُها هو المجهول، وهو يحتوي ذلك المجهول." },
      { en: "Lesson 4 computed it on all 503 rows, so the ratio is only unusable until you re-fit it on the training rows.",
        ar: "حسبه الدرس 4 على الصفوف الـ503 كلها، فالنسبةُ غيرُ قابلة للاستعمال فقط حتى تعيد ضبطها على صفوف التدريب." },
      { en: "The ratio has 117 blank deposits, and a feature may not carry more missing values than the target does.",
        ar: "للنسبة 117 تأمينًا فارغًا، ولا يجوز أن تحمل السمةُ قيمًا مفقودة أكثر من الهدف." },
      { en: "Division creates floating-point values whose scale must be fitted, which is why Lesson 7 prefers bands over ratios.",
        ar: "القسمةُ تُنشئ قيمًا عشرية يجب ضبطُ مقياسها، ولهذا يفضّل الدرس 7 النطاقات على النسب." } ],
    answer: 0,
    hint: { en: "Ask the first gate's question about the ratio: at the moment you need the prediction, do you have every value it is built from?",
            ar: "اسأل سؤالَ البوابة الأولى عن النسبة: في اللحظة التي تحتاج فيها التنبؤ، هل تملك كلَّ قيمة بُنيت منها؟" },
    explain: { en: "The same expression is legitimate in one role and disqualified in the other, and the role is decided by <em>when</em> it is computed and <em>what is known then</em>. As a diagnostic it is applied to recorded rows to find the two whose ratio is not 1, 2 or 3 months — a job that needs the rent and has it. As a feature it would have to be available for a flat whose rent you are predicting, and if you knew the rent you would not be predicting it. The second option is the dangerous distractor because it names a real discipline and applies it to the wrong failure: re-fitting cures a mis-fitted parameter, and nothing cures a column built out of the target. The third invents a rule about missingness, and the fourth describes scaling, which is a different concern entirely.",
              ar: "التعبيرُ نفسه مشروعٌ في دور ومستبعَدٌ في آخر، والدورُ يحدّده <em>متى</em> يُحسَب و<em>ما المعلوم</em> حينئذ. فتشخيصًا يُطبَّق على صفوف مسجَّلة لإيجاد الصفّين اللذين ليست نسبتهما 1 أو 2 أو 3 أشهر — عملٌ يحتاج الإيجارَ ويملكه. وسمةً سيلزم أن يكون متاحًا لشقة تتنبّأ بإيجارها، ولو عرفتَ الإيجارَ لما كنتَ تتنبّأ به. والخيارُ الثاني هو المضلّلُ الخطير فهو يسمّي انتظامًا حقيقيًّا ويطبّقه على الفشل الخاطئ: فإعادةُ الضبط تشفي وسيطًا سيّئَ الضبط، ولا شيء يشفي عمودًا مبنيًّا من الهدف. والثالثُ يختلق قاعدةً عن النقص، والرابعُ يصف توحيدَ المقياس وهو شأنٌ آخر تمامًا." } }

  ]
};
